import { defineStore } from "pinia";
import { ref } from "vue";

export const modifyUiStore = defineStore("modify", () => {
  const showBackEle = ref(false);
  const backDataList = ref({});
  const modifyType = ref("");
  const modifyData = ref("");
  const showModifyEle = ref(false);

  const ModifyUserRole = async (inputData) => {
    const responsePost = await fetch("/api/modify-user", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(inputData),
    });

    if (!responsePost.ok) {
      throw new Error("Network response was not ok");
    }
  };

  return {
    showBackEle,
    backDataList,
    modifyType,
    modifyData,
    showModifyEle,
    ModifyUserRole,
  };
});
